/** Translates one string (whitespace around it is kept). */
export function t(s: string): string {
  if (current === 'en' || !s) return s;
  // Separators around an interpolated piece (" · Verified booking") stay as they are.
  const m0 = s.match(/^([\s·,]*)(.*?)([\s·,]*)$/s)!;
  const [, lead, core, trail] = m0;
  if (!core) return s;
  const hit = DE[core];
  if (hit !== undefined) return lead + hit + trail;
  for (const [re, rep] of PATTERNS) {
    const m = core.match(re);
    // `{$n}` means: translate that captured part too.
    if (m) return lead + rep.replace(/\{\$(\d)\}/g, (_, i) => t(m[+i])).replace(/\$(\d)/g, (_, i) => m[+i]) + trail;
  }
  return s;
}
